def _align_api_if_sparse(X):
    """
    Convert to sparse interface as set in config.

    Input can be dense or sparse.
    If sparse, convert to sparse_interface indicated by get_config.
    Otherwise, return X unchanged.
    """
    if not sp.sparse.issparse(X):
        return X

    config_sparse_interface = get_config()["sparse_interface"]

    # there are only two sparse interfaces: sparray and spmatrix
    if config_sparse_interface == "sparray":
        if sp.sparse.isspmatrix(X):
            # Fundamental code to switch to sparray in any format
            return getattr(sp.sparse, X.format + "_array")(X)
        return X
    elif config_sparse_interface == "spmatrix":
        if sp.sparse.isspmatrix(X):
            return X
        # Fundamental code to switch to spmatrix in any format
        return getattr(sp.sparse, X.format + "_matrix")(X)
    else:
        raise ValueError(
            f'Config "sparse_interface" is {config_sparse_interface}. '
            'It should be either "sparray" or "spmatrix".'
        )

def _retry_with_clean_cache(
    openml_path: str,
    data_home: Optional[str],
    no_retry_exception: Optional[Exception] = None,
) -> Callable:
    """If the first call to the decorated function fails, the local cached file
    (if any) is removed and the function is called again. The retry happens
    whether or not ``data_home`` is set: when caching is disabled there is no
    file to remove and the function is simply called a second time. We can
    provide a specific exception to not retry on using `no_retry_exception`
    parameter.
    """

    def decorator(f):
        @wraps(f)
        def wrapper(*args, **kw):
            try:
                return f(*args, **kw)
            except URLError:
                raise
            except Exception as exc:
                if no_retry_exception is not None and isinstance(
                    exc, no_retry_exception
                ):
                    raise
                if data_home is None:
                    warn(
                        "Downloaded file could have been corrupted, redownloading.",
                        RuntimeWarning,
                    )
                else:
                    local_path = _get_local_path(openml_path, data_home)
                    warn(
                        f"Invalid cache, redownloading file to {local_path}",
                        RuntimeWarning,
                    )
                    Path(local_path).unlink(missing_ok=True)
                return f(*args, **kw)

        return wrapper

    return decorator

